import '../../../../../../Core/Models/cart_itemes.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';class CartSources {  static Future<CartItemsModel> getCarts() async {    final response = await DioHelper.getData(      path: ApiEndpoints.cart,    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  } static Future<CartItemsModel> removeFromCart({required int id}) async {    final response = await DioHelper.deleteData(      path: "${ApiEndpoints.removeCart}/$id",    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  }  static Future<CartItemsModel> updateFromCart(      {required int id, required int newQuantity}) async {    final response = await DioHelper.putData(      data: {"quantity": newQuantity},      path: "${ApiEndpoints.updateCart}/$id",    );    final data = CartItemsModel.fromJson(response.data["data"]);    return data;  }  //* Coupons  Future<void> getCoupon({required String id}) async {}  Future<void> applyCoupon({required String id}) async {}  Future<void> removeCoupon({required String id}) async {}}